package securestore

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/binary"
	"errors"
	"io"
	"sync"
	"time"

	"golang.org/x/crypto/scrypt"
)

var (
	ErrDecryption    = errors.New("decryption failed")
	ErrCircuitOpen   = errors.New("circuit breaker open")
	ErrSerialization = errors.New("serialization error")
)

// domainSalt provides domain separation for the KDF. In a real deployment a
// unique per-serializer random salt should be stored alongside the ciphertext;
// this fixed salt at minimum adds a memory-hard work factor over raw SHA-256.
var domainSalt = []byte("securestore/v1/kdf-salt")

type CircuitState int

const (
	StateClosed CircuitState = iota
	StateOpen
	StateHalfOpen
)

type CircuitBreaker struct {
	mu           sync.Mutex
	state        CircuitState
	failureCount int
	threshold    int
	resetTimeout time.Duration
	lastFailure  time.Time
}

func NewCircuitBreaker(threshold int, timeout time.Duration) *CircuitBreaker {
	return &CircuitBreaker{
		state:        StateClosed,
		threshold:    threshold,
		resetTimeout: timeout,
	}
}

func (cb *CircuitBreaker) Execute(fn func() error) error {
	cb.mu.Lock()
	if cb.state == StateOpen {
		if time.Since(cb.lastFailure) > cb.resetTimeout {
			cb.state = StateHalfOpen
		} else {
			cb.mu.Unlock()
			return ErrCircuitOpen
		}
	}
	cb.mu.Unlock()

	err := fn()

	cb.mu.Lock()
	defer cb.mu.Unlock()
	if err != nil {
		cb.failureCount++
		cb.lastFailure = time.Now()
		if cb.failureCount >= cb.threshold {
			cb.state = StateOpen
		}
	} else {
		cb.failureCount = 0
		cb.state = StateClosed
	}
	return err
}

type SecureSerializer struct {
	key     []byte
	breaker *CircuitBreaker
}

func NewSecureSerializer(passphrase string) (*SecureSerializer, error) {
	// Use a memory-hard KDF (scrypt) instead of a single unsalted SHA-256 pass.
	key, err := scrypt.Key([]byte(passphrase), domainSalt, 1<<15, 8, 1, 32)
	if err != nil {
		return nil, err
	}
	return &SecureSerializer{
		key:     key,
		breaker: NewCircuitBreaker(5, 30*time.Second),
	}, nil
}

func pkcs7Pad(data []byte, blockSize int) []byte {
	padLen := blockSize - (len(data) % blockSize)
	padding := make([]byte, padLen)
	for i := range padding {
		padding[i] = byte(padLen)
	}
	return append(data, padding...)
}

func (s *SecureSerializer) Serialize(obj map[string]string) ([]byte, error) {
	var buf []byte
	for k, v := range obj {
		kBytes := []byte(k)
		vBytes := []byte(v)
		lenBuf := make([]byte, 4)
		binary.BigEndian.PutUint32(lenBuf, uint32(len(kBytes)))
		buf = append(buf, lenBuf...)
		buf = append(buf, kBytes...)
		binary.BigEndian.PutUint32(lenBuf, uint32(len(vBytes)))
		buf = append(buf, lenBuf...)
		buf = append(buf, vBytes...)
	}
	return s.encrypt(buf)
}

func (s *SecureSerializer) Deserialize(ciphertext []byte) (map[string]string, error) {
	var result map[string]string
	var deserErr error

	execErr := s.breaker.Execute(func() error {
		plaintext, err := s.decrypt(ciphertext)
		if err != nil {
			return err
		}
		result, deserErr = parseKV(plaintext)
		if deserErr != nil {
			return ErrSerialization
		}
		return nil
	})

	if execErr != nil {
		return nil, execErr
	}
	return result, nil
}

func (s *SecureSerializer) encrypt(plaintext []byte) ([]byte, error) {
	block, err := aes.NewCipher(s.key)
	if err != nil {
		return nil, err
	}
	padded := pkcs7Pad(plaintext, aes.BlockSize)
	ciphertext := make([]byte, aes.BlockSize+len(padded))
	iv := ciphertext[:aes.BlockSize]
	if _, err := io.ReadFull(rand.Reader, iv); err != nil {
		return nil, err
	}
	mode := cipher.NewCBCEncrypter(block, iv)
	mode.CryptBlocks(ciphertext[aes.BlockSize:], padded)
	return ciphertext, nil
}

func (s *SecureSerializer) decrypt(ciphertext []byte) ([]byte, error) {
	block, err := aes.NewCipher(s.key)
	if err != nil {
		return nil, ErrDecryption
	}
	if len(ciphertext) < aes.BlockSize*2 || len(ciphertext)%aes.BlockSize != 0 {
		return nil, ErrDecryption
	}
	iv := ciphertext[:aes.BlockSize]
	data := ciphertext[aes.BlockSize:]
	mode := cipher.NewCBCDecrypter(block, iv)
	plaintext := make([]byte, len(data))
	mode.CryptBlocks(plaintext, data)

	// Validate padding without leaking which step failed
	padLen := int(plaintext[len(plaintext)-1])
	validPad := true
	if padLen == 0 || padLen > aes.BlockSize {
		validPad = false
		padLen = 1 // prevent index issues but still check all
	}
	for i := len(plaintext) - padLen; i < len(plaintext); i++ {
		if i >= 0 && plaintext[i] != byte(padLen) {
			validPad = false
		}
	}
	if !validPad {
		return nil, ErrDecryption
	}
	return plaintext[:len(plaintext)-padLen], nil
}

func parseKV(data []byte) (map[string]string, error) {
	result := make(map[string]string)
	offset := 0
	for offset < len(data) {
		if offset+4 > len(data) {
			return nil, ErrSerialization
		}
		kLen := int(binary.BigEndian.Uint32(data[offset : offset+4]))
		offset += 4
		if offset+kLen > len(data) {
			return nil, ErrSerialization
		}
		key := string(data[offset : offset+kLen])
		offset += kLen
		if offset+4 > len(data) {
			return nil, ErrSerialization
		}
		vLen := int(binary.BigEndian.Uint32(data[offset : offset+4]))
		offset += 4
		if offset+vLen > len(data) {
			return nil, ErrSerialization
		}
		value := string(data[offset : offset+vLen])
		offset += vLen
		result[key] = value
	}
	return result, nil
}
